<script lang="ts">
	import{onMount}from'svelte';import{api}from'$lib/api';import { formatMoney } from '$lib/money';let{params}=$props();type Payment={id:string;booking_id:string|null;provider:string;environment:string;reference:string;amount_minor:number;currency:string;state:string;created_at:string;last_verified_at:string|null;allocation_id:string|null;route:string|null;gross_minor:number|null;deduction_minor:number|null;seller_entitlement_minor:number|null;settlement_state:string|null;processor_cost_minor:number|null;card_country:string|null;card_brand:string|null};let item=$state<Payment|null>(null);let message=$state('');let loading=$state(true);
	onMount(async()=>{try{item=await api<Payment>(`/api/v1/ops/payments/${encodeURIComponent(params.id)}`)}catch(e){message=e instanceof Error?e.message:'The payment record could not be loaded.'}finally{loading=false}});
</script>
<svelte:head><title>Payment detail — Ops · WantMyTime</title></svelte:head><section class="form-page app-page"><a class="back-link" href="/ops/payments">← Payments</a><p class="eyebrow">Payment attempt</p>{#if loading}<p class="page-intro">Loading record…</p>{:else if !item}<h1 class="page-heading">Record unavailable.</h1><p class="page-intro">{message}</p>{:else}<h1 class="page-heading">{formatMoney(item.amount_minor,item.currency)}</h1><div class="appointment-slip"><div><small>STATE</small><strong>{item.state.replaceAll('_',' ')}</strong></div><div><small>PROVIDER</small><strong>{item.provider} · {item.environment}</strong></div><div><small>BOOKING</small><strong>{#if item.booking_id}<a href={`/ops/bookings/${encodeURIComponent(item.booking_id)}`}>{item.booking_id} ↗</a>{:else}Not booked yet{/if}</strong></div><div><small>REFERENCE</small><strong>{item.reference}</strong></div>{#if item.card_country}<div><small>CARD</small><strong>{item.card_brand?item.card_brand.toUpperCase()+' · ':''}{item.card_country}{item.card_country!=='NG'?' (international)':''}</strong></div>{/if}{#if item.processor_cost_minor!==null}<div><small>PROVIDER FEE</small><strong>{formatMoney(item.processor_cost_minor,item.currency)}{item.deduction_minor!==null&&item.processor_cost_minor>item.deduction_minor?` · ${formatMoney(item.processor_cost_minor-item.deduction_minor,item.currency)} over the platform fee`:''}</strong></div>{/if}</div><section class="readiness-panel"><h2>Allocation</h2>{#if item.allocation_id}<p>Gross {formatMoney(item.gross_minor||0,item.currency)} · deduction {formatMoney(item.deduction_minor||0,item.currency)} · seller entitlement {formatMoney(item.seller_entitlement_minor||0,item.currency)}</p><p>Route: {item.route?.replaceAll('_',' ')} · settlement state: {item.settlement_state?.replaceAll('_',' ')||'unknown'}</p>{:else}<p>No verified allocation is attached to this attempt.</p>{/if}<p>Last provider verification: {item.last_verified_at?new Date(item.last_verified_at).toLocaleString():'Not recorded'}</p></section><div class="notice notice-warning">Payment status changes only after a fresh provider verification. Review the provider event inbox for failed verification attempts.</div>{/if}</section>
